    W('pisa', 'class_officer', 'ក្នុងថ្នាក់រៀនមួយមានសិស្សស្រី ១៤ នាក់ និងសិស្សប្រុស ១០ នាក់។ ក្នុងនោះមានធីតា (ស្រី) និងរដ្ឋា (ប្រុស)។ គេចាប់ឆ្នោតជ្រើសរើសសិស្សម្នាក់ជាប្រធានថ្នាក់។ ក. គណនាប្រូបាបដែលប្រធានថ្នាក់ជាសិស្សស្រី។ ខ. គណនាប្រូបាបដែលប្រធានថ្នាក់ជាធីតា ឬរដ្ឋា។ គ. គណនាប្រូបាបដែលប្រធានថ្នាក់មិនមែនជាធីតា ហើយក៏មិនមែនជារដ្ឋា។', [
        ('ក. សិស្សសរុប ៖ ' + M('N = 14 + 10 = 24\\ \\text{នាក់}'), 1),
        ('ប្រូបាបប្រធានថ្នាក់ជាសិស្សស្រី ៖ ' + M('P(\\text{ស្រី}) = \\dfrac{14}{24} = \\dfrac{7}{12} \\approx 58.33\\%'), 1),
        ('ខ. ករណីស្របធីតា ឬរដ្ឋា មាន 2 នាក់ នាំឱ្យ ' + M('P = \\dfrac{2}{24} = \\dfrac{1}{12} \\approx 8.33\\%'), 1),
        ('គ. ចំនួនសិស្សដែលមិនមែនធីតា និងរដ្ឋា ៖ ' + M('24 - 2 = 22\\ \\text{នាក់}'), 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{22}{24} = \\dfrac{11}{12} \\approx 91.67\\%'), 1)])

    W('pisa', 'exam_prep', 'លោកគ្រូដាក់ ៦ សំណួរ (' + M('A, B, C, D, E, F') + ') ឱ្យសិស្សរៀន។ សិស្សម្នាក់រៀនចេះតែ ៤ សំណួរ (' + M('A, B, C, D') + ')។ ក្នុងវិញ្ញាសាប្រឡង គ្រូចាប់ឆ្នោតជ្រើស ២ សំណួរ។ ក. រកចំនួនករណីអាចទាំងអស់នៃការចេញ ២ សំណួរ។ ខ. គណនាប្រូបាបដែលវិញ្ញាសាចេញត្រូវនឹងសំណួរដែលសិស្សនោះចេះទាំងពីរ។ គ. គណនាប្រូបាបដែលវិញ្ញាសាចេញប៉ះសំណួរដែលសិស្សមិនចេះទាំងពីរ។', [
        ('ក. ករណីអាចនៃការចាប់ ២ ក្នុងចំណោម ៦ គឺ ' + M('N = 15\\ \\text{ករណី}'), 1),
        ('ខ. ករណីស្របដែលសិស្សចេះទាំងពីរ (គូពី ' + M('\\{A,B,C,D\\}') + ') មាន 6 ករណី', 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{6}{15} = \\dfrac{2}{5} = 40\\%'), 1),
        ('គ. ករណីស្របមិនចេះទាំងពីរ (គូពី ' + M('\\{E,F\\}') + ') គឺ ' + M('\\{EF\\} \\implies n = 1'), 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{1}{15} \\approx 6.67\\%'), 1)])

    W('pisa', 'three_colors', 'ក្នុងប្រអប់មួយមានបាល់ ២៤ គ្រាប់ដែលមានពណ៌ក្រហម បៃតង និងខៀវ។ ប្រូបាបនៃការចាប់បានបាល់ពណ៌ក្រហមគឺ ' + M('\\dfrac{1}{3}') + ' និងពណ៌បៃតងគឺ ' + M('\\dfrac{1}{6}') + '។ ក. គណនាប្រូបាបនៃការចាប់បានបាល់ពណ៌ខៀវ។ ខ. រកចំនួនបាល់ពណ៌នីមួយៗក្នុងប្រអប់។ គ. បើគេដកបាល់ក្រហមចេញ ២ គ្រាប់ រកប្រូបាបថ្មីនៃការចាប់បានបាល់ពណ៌ក្រហម។', [
        ('ក. ប្រូបាបបាល់ខៀវ ៖ ' + M('P(\\text{ខៀវ}) = 1 - \\left(\\dfrac{1}{3} + \\dfrac{1}{6}\\right) = 1 - \\dfrac{1}{2} = \\dfrac{1}{2} = 50\\%'), 2),
        ('ខ. ក្រហម ៖ ' + M('24 \\times \\dfrac{1}{3} = 8') + ' គ្រាប់, បៃតង ៖ ' + M('24 \\times \\dfrac{1}{6} = 4') + ' គ្រាប់, ខៀវ ៖ ' + M('24 \\times \\dfrac{1}{2} = 12') + ' គ្រាប់', 2),
        ('គ. បាល់សរុបថ្មី 22 គ្រាប់, ក្រហមសល់ 6 គ្រាប់ នាំឱ្យ ' + M('P_2(\\text{ក្រហម}) = \\dfrac{6}{22} = \\dfrac{3}{11} \\approx 27.27\\%'), 1)])

    W('pisa', 'company_trip', 'ក្រុមហ៊ុនមួយមានបុគ្គលិក ៤ នាក់ គឺនារី ២ នាក់ (' + M('F_1, F_2') + ') និងបុរស ២ នាក់ (' + M('M_1, M_2') + ')។ ក្រុមហ៊ុនចាប់ឆ្នោតជ្រើសរើស ២ នាក់ដោយចៃដន្យទៅដើរកម្សាន្ត។ ក. កំណត់លំហសំណាក និងចំនួនករណីអាចទាំងអស់។ ខ. គណនាប្រូបាបដែលជ្រើសបាននារី ១ នាក់ និងបុរស ១ នាក់។ គ. គណនាប្រូបាបដែលជ្រើសបានសុទ្ធតែនារី។', [
        ('ក. លំហសំណាក ៖ ' + M('S = \\{F_1F_2, F_1M_1, F_1M_2, F_2M_1, F_2M_2, M_1M_2\\} \\implies N = 6'), 1),
        ('ខ. ករណីស្របនារី ១ បុរស ១ ៖ ' + M('\\{F_1M_1, F_1M_2, F_2M_1, F_2M_2\\} \\implies n = 4'), 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{4}{6} = \\dfrac{2}{3} \\approx 66.67\\%'), 1),
        ('គ. ករណីស្របសុទ្ធតែនារី ៖ ' + M('\\{F_1F_2\\} \\implies n = 1'), 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{1}{6} \\approx 16.67\\%'), 1)])

    W('pisa', 'spinner_game', 'ក្នុងល្បែងកម្សាន្តមួយ គេបង្វិលថាសមូលមួយដែលមាន ៤ ផ្នែកស្មើគ្នា លាបពណ៌បៃតង ស ខ្មៅ និងក្រហម។ បើព្រួញឈប់ចំពណ៌បៃតង អ្នកលេងឈ្នះ ២០០០០៛ ចំពណ៌ស ឈ្នះ ១០០០០៛ ចំពណ៌ក្រហម ឬខ្មៅ មិនបានរង្វាន់ទេ។ ក. គណនាប្រូបាបដែលព្រួញឈប់ចំពណ៌បៃតង។ ខ. គណនាប្រូបាបដែលអ្នកលេងទទួលបានរង្វាន់។ គ. គណនាប្រាក់រង្វាន់រំពឹងទុក (មធ្យម) ក្នុងការបង្វិល ១ លើក។', [
        ('ក. ថាសចែកជា ៤ ផ្នែកស្មើគ្នា នាំឱ្យ ' + M('P(\\text{បៃតង}) = \\dfrac{1}{4} = 25\\%'), 1),
        ('ខ. ទទួលបានរង្វាន់ (បៃតង ឬ ស) មាន 2 ករណី', 1),
        ('ប្រូបាប ៖ ' + M('P = \\dfrac{2}{4} = \\dfrac{1}{2} = 50\\%'), 1),
        ('គ. ប្រាក់រំពឹងទុក ៖ ' + M('E = 20000\\left(\\dfrac{1}{4}\\right) + 10000\\left(\\dfrac{1}{4}\\right) + 0\\left(\\dfrac{1}{2}\\right)'), 1),
        (M('E = 5000 + 2500 = 7\\,500\\ \\text{៛}'), 1)], FIG_SPINNER)

    return C
